capture_editorial_notification.definition:
CREATE OR REPLACE FUNCTION public.capture_editorial_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare changed boolean; hours integer;
begin
  changed := TG_OP='INSERT';
  if TG_OP='UPDATE' then
    changed := new.assigned_to is distinct from old.assigned_to
      or new.review_due_at is distinct from old.review_due_at
      or (new.status in ('draft','pending_review')) <> (old.status in ('draft','pending_review'));
  end if;
  if changed then
    new.notification_epoch := coalesce(new.notification_epoch,0)+1;
    if new.assigned_to is not null and new.status in ('draft','pending_review') then
      new.review_assigned_at := statement_timestamp();
      if new.review_due_at is null then
        select deadline_hours into hours from public.editorial_notification_policy;
        new.review_due_at := statement_timestamp() + make_interval(hours=>hours);
      end if;
    end if;
  end if;
  return new;
end $function$

edge_api_choose_review.definition:
CREATE OR REPLACE FUNCTION public.edge_api_choose_review(p_user_id uuid, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_concept uuid;
begin
  select (now() at time zone timezone)::date into v_today
    from public.profiles where id = p_user_id for update;
  if v_today is null then return null; end if;
  v_today := coalesce(p_today, v_today);

  if exists(select 1 from public.daily_reviews
    where user_id = p_user_id and assigned_for = v_today) then
    return public.edge_api_review_payload(p_user_id, v_today);
  end if;
  if exists(select 1 from public.daily_assignments
    where user_id = p_user_id and assigned_for = v_today) then
    return null;
  end if;
  -- An intentionally empty followed set cannot be widened by a review.
  select a.concept_id into v_concept
    from public.daily_assignments a
    join public.concepts c on c.id = a.concept_id and c.status = 'published'
    join public.topics t on t.id = c.topic_id and t.is_active
    join public.subtopics s on s.id = c.subtopic_id and s.is_active
    join public.user_topics ut on ut.topic_id = c.topic_id and ut.user_id = p_user_id
    left join lateral (
      select max(r.assigned_for) as last_review from public.daily_reviews r
       where r.user_id = p_user_id and r.concept_id = a.concept_id
    ) seen on true
   where a.user_id = p_user_id and a.completed_at is not null
   order by seen.last_review asc nulls first, a.assigned_for, a.concept_id
   limit 1;
  if v_concept is null then return null; end if;
  insert into public.daily_reviews(user_id, concept_id, assigned_for)
  values (p_user_id, v_concept, v_today)
  on conflict(user_id, assigned_for) do nothing;
  return public.edge_api_review_payload(p_user_id, v_today);
end
$function$

edge_api_complete_daily.definition:
CREATE OR REPLACE FUNCTION public.edge_api_complete_daily(p_user_id uuid, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_assignment record;
  v_subtopic jsonb;
begin
  select (now() at time zone timezone)::date into v_today
    from public.profiles where id = p_user_id for update;
  if v_today is null then return null; end if;
  v_today := coalesce(p_today, v_today);

  update public.daily_assignments
     set completed_at = coalesce(completed_at, now())
   where id = (
     select id from public.daily_assignments
      where user_id = p_user_id
        and assigned_for in (v_today, v_today - 1)
        and not exists(select 1 from public.daily_reviews r
          where r.user_id = p_user_id and r.assigned_for >= daily_assignments.assigned_for)
      order by assigned_for desc limit 1
   )
  returning id, concept_id, assigned_for, completed_at into v_assignment;
  if not found then return null; end if;

  insert into public.user_concept_completions
    (user_id, concept_id, source_assignment_id, completed_at)
  values (p_user_id, v_assignment.concept_id, v_assignment.id, v_assignment.completed_at)
  on conflict(user_id, concept_id) do nothing;
  v_subtopic := public.edge_api_record_subtopic_completion(p_user_id, v_assignment.concept_id);
  perform public.edge_api_award_eligible(p_user_id);
  return jsonb_build_object(
    'completed', true, 'assigned_for', v_assignment.assigned_for,
    'stats', public.edge_api_stats(p_user_id),
    'subtopic_completion', v_subtopic
  );
end
$function$

edge_api_complete_review.definition:
CREATE OR REPLACE FUNCTION public.edge_api_complete_review(p_user_id uuid, p_review_id uuid, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_day date;
begin
  select (now() at time zone timezone)::date into v_today
    from public.profiles where id = p_user_id for update;
  if v_today is null then return null; end if;
  v_today := coalesce(p_today, v_today);
  update public.daily_reviews r
     set completed_at = coalesce(completed_at, now())
   where r.id = p_review_id and r.user_id = p_user_id
     and (r.completed_at is not null or (
       r.assigned_for in (v_today, v_today - 1)
       and not exists(select 1 from public.daily_assignments a
         where a.user_id = p_user_id and a.assigned_for > r.assigned_for)
       and not exists(select 1 from public.daily_reviews newer
         where newer.user_id = p_user_id and newer.assigned_for > r.assigned_for)
     ))
  returning r.assigned_for into v_day;
  if not found then return null; end if;
  perform public.edge_api_award_eligible(p_user_id);
  return jsonb_build_object(
    'completed', true, 'assigned_for', v_day,
    'stats', public.edge_api_stats(p_user_id),
    'subtopic_completion', null
  );
end
$function$

edge_api_daily.definition:
CREATE OR REPLACE FUNCTION public.edge_api_daily(p_user_id uuid, p_low integer DEFAULT 10, p_reserve integer DEFAULT 60, p_active_days integer DEFAULT 90, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_timezone text;
  v_concept uuid;
  v_topic uuid;
  v_assignment uuid;
  v_payload jsonb;
begin
  if p_low < 0 or p_low > 30 or p_reserve < 1 or p_reserve > 365
     or p_active_days < 1 or p_active_days > 365 then
    raise exception 'Invalid supply configuration';
  end if;

  -- Match the legacy-user safety net without restoring deliberately unfollowed topics.
  with created as (
    insert into public.profiles(id, display_name)
    select p_user_id, split_part(u.email, '@', 1)
      from auth.users u where u.id = p_user_id
    on conflict(id) do nothing returning id
  ), prefs as (
    insert into public.notification_preferences(user_id) values (p_user_id)
    on conflict(user_id) do nothing
  )
  insert into public.user_topics(user_id, topic_id)
  select created.id, t.id from created cross join public.topics t where t.is_active
  on conflict do nothing;

  select timezone into v_timezone
    from public.profiles where id = p_user_id for update;
  if v_timezone is null then
    raise exception 'Profile unavailable';
  end if;
  v_today := coalesce(p_today, (now() at time zone v_timezone)::date);

  if exists(select 1 from public.daily_reviews
    where user_id = p_user_id and assigned_for = v_today) then
    return jsonb_build_object('assigned_for', v_today, 'reason', 'catalog_exhausted',
      'detail', 'You have already been assigned every available concept.');
  end if;
  if exists(select 1 from public.daily_assignments
    where user_id = p_user_id and assigned_for = v_today) then
    v_payload := public.edge_api_daily_payload(p_user_id, v_today);
    if v_payload is not null then return v_payload; end if;
    return jsonb_build_object('assigned_for', v_today, 'reason', 'catalog_exhausted',
      'detail', 'You have already been assigned every available concept.');
  end if;

  if not exists(select 1 from public.user_topics ut
    join public.topics t on t.id = ut.topic_id and t.is_active
    where ut.user_id = p_user_id) then
    return jsonb_build_object('assigned_for', v_today, 'reason', 'personalization_required',
      'detail', 'Follow at least one topic to receive a daily concept.');
  end if;

  -- Move the most recent unfinished followed lesson, retaining its identity and timestamp.
  with pending as (
    select a.id from public.daily_assignments a
    join public.concepts c on c.id = a.concept_id and c.status = 'published'
    join public.topics t on t.id = c.topic_id and t.is_active
    join public.subtopics s on s.id = c.subtopic_id and s.is_active
    join public.user_topics ut on ut.topic_id = c.topic_id and ut.user_id = p_user_id
    where a.user_id = p_user_id and a.completed_at is null and a.assigned_for < v_today
    order by a.assigned_for desc, a.id limit 1
  )
  update public.daily_assignments a set assigned_for = v_today
    from pending where a.id = pending.id returning a.concept_id into v_concept;
  if v_concept is not null then
    select topic_id into v_topic from public.concepts where id = v_concept;
    perform public.edge_api_signal_supply(p_user_id, v_topic, p_low, p_reserve, p_active_days);
    return public.edge_api_daily_payload(p_user_id, v_today);
  end if;

  with pool as (
    select c.id, c.topic_id, coalesce(c.difficulty, 1) as level,
      (select count(*) from jsonb_array_elements_text(
        coalesce(c.curriculum->'prerequisites', '[]'::jsonb)) required(slug)
        where not exists(select 1 from public.daily_assignments learned
          join public.concepts prior on prior.id = learned.concept_id
          where learned.user_id = p_user_id and learned.completed_at is not null
            and prior.slug = required.slug)) as unmet
      from public.concepts c
      join public.topics t on t.id = c.topic_id and t.is_active
      join public.subtopics s on s.id = c.subtopic_id and s.is_active
      where c.status = 'published'
        and exists(select 1 from public.user_topics ut
          where ut.user_id = p_user_id and ut.topic_id = c.topic_id)
        and not exists(select 1 from public.daily_assignments a
          where a.user_id = p_user_id and a.concept_id = c.id)
  ), last_seen as (
    select c.topic_id, max(a.assigned_for) as seen_on
      from public.daily_assignments a
      join public.concepts c on c.id = a.concept_id and c.status = 'published'
     where a.user_id = p_user_id group by c.topic_id
  )
  select pool.id, pool.topic_id into v_concept, v_topic
    from pool left join last_seen on last_seen.topic_id = pool.topic_id
   order by last_seen.seen_on asc nulls first, pool.unmet asc, pool.level asc, random()
   limit 1;

  if v_concept is not null then
    begin
      insert into public.daily_assignments(id, user_id, concept_id, assigned_for)
      values (gen_random_uuid(), p_user_id, v_concept, v_today)
      on conflict(user_id, assigned_for) do nothing returning id into v_assignment;
    exception when unique_violation then
      v_assignment := null;
    end;
    if v_assignment is not null then
      perform public.edge_api_signal_supply(p_user_id, v_topic, p_low, p_reserve, p_active_days);
      v_payload := public.edge_api_daily_payload(p_user_id, v_today);
      if v_payload is not null then return v_payload; end if;
    else
      v_payload := public.edge_api_daily_payload(p_user_id, v_today);
      if v_payload is not null then return v_payload; end if;
    end if;
  else
    -- Request future supply in a followed topic without waiting for generation.
    select ut.topic_id into v_topic from public.user_topics ut
    join public.topics t on t.id = ut.topic_id and t.is_active
    left join (
      select c.topic_id, max(a.assigned_for) as seen_on
      from public.daily_assignments a
      join public.concepts c on c.id = a.concept_id and c.status = 'published'
      where a.user_id = p_user_id group by c.topic_id
    ) seen on seen.topic_id = ut.topic_id
    where ut.user_id = p_user_id
    order by seen.seen_on asc nulls first limit 1;
    if v_topic is not null then
      perform public.edge_api_signal_supply(p_user_id, v_topic, p_low, p_reserve, p_active_days);
    end if;
  end if;
  return jsonb_build_object('assigned_for', v_today, 'reason', 'catalog_exhausted',
    'detail', 'You have already been assigned every available concept.');
end
$function$

edge_api_editorial_me.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_me(p_user_id uuid, p_session_id uuid, p_aal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_member public.editorial_memberships%rowtype;
begin
  if p_session_id is null or not exists(
    select 1 from auth.users u join auth.sessions s on s.user_id = u.id
     where u.id = p_user_id and s.id = p_session_id
       and u.email_confirmed_at is not null
       and (u.banned_until is null or u.banned_until <= statement_timestamp())
       and (s.not_after is null or s.not_after > statement_timestamp())
  ) then
    return jsonb_build_object('error', 'session_required');
  end if;
  select * into v_member from public.editorial_memberships
   where user_id = p_user_id and status = 'active';
  if not found then return jsonb_build_object('error', 'unavailable'); end if;
  return jsonb_build_object(
    'member', to_jsonb(v_member),
    'onboarding_required', v_member.requested_name is null,
    'name_approval_pending', v_member.requested_name is distinct from v_member.approved_name,
    'mfa_required', v_member.require_mfa and p_aal is distinct from 'aal2'
  );
end
$function$

edge_api_push_token.definition:
CREATE OR REPLACE FUNCTION public.edge_api_push_token(p_user_id uuid, p_token text, p_platform text, p_register boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_register is null then
    raise exception 'Invalid push-token action';
  end if;
  if p_register then
    if p_token is null or length(p_token) not between 10 and 200
       or (p_platform is not null and p_platform not in ('ios', 'android')) then
      raise exception 'Invalid push token';
    end if;
    insert into public.device_tokens(user_id, expo_push_token, platform)
    values(p_user_id, p_token, p_platform)
    on conflict (expo_push_token) do update
      set user_id = excluded.user_id,
          platform = coalesce(excluded.platform, device_tokens.platform),
          last_seen_at = now();
  elsif p_token is null then
    delete from public.device_tokens where user_id = p_user_id;
  else
    delete from public.device_tokens
    where user_id = p_user_id and expo_push_token = p_token;
  end if;
  return true;
end
$function$

edge_api_set_interaction.definition:
CREATE OR REPLACE FUNCTION public.edge_api_set_interaction(p_user_id uuid, p_slug text, p_kind text, p_on boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_concept_id uuid;
begin
  if p_kind not in ('like', 'save') or p_on is null then
    raise exception 'Invalid interaction';
  end if;

  select id into v_concept_id from public.concepts
  where slug = p_slug and status = 'published';
  if v_concept_id is null then
    return false;
  end if;

  if p_kind = 'like' then
    insert into public.concept_interactions(user_id, concept_id, liked_at)
    values (p_user_id, v_concept_id, case when p_on then now() else null end)
    on conflict (user_id, concept_id) do update
      set liked_at = excluded.liked_at, updated_at = now();
  else
    insert into public.concept_interactions(user_id, concept_id, saved_at)
    values (p_user_id, v_concept_id, case when p_on then now() else null end)
    on conflict (user_id, concept_id) do update
      set saved_at = excluded.saved_at, updated_at = now();
  end if;
  return true;
end
$function$

edge_api_state.definition:
CREATE OR REPLACE FUNCTION public.edge_api_state(p_user_id uuid, p_compact boolean, p_reviews boolean, p_low integer, p_reserve integer, p_active_days integer, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_profile record;
  v_daily jsonb;
  v_review jsonb;
  v_history jsonb;
  v_saved jsonb;
  v_stats jsonb;
  v_followed jsonb;
  v_likes jsonb;
  v_bookmarks jsonb;
  v_versions jsonb;
  v_older jsonb;
  v_availability text;
  v_assignment_slug text;
  v_limit integer;
begin
  if p_compact is null or p_reviews is null then
    raise exception 'Invalid state options';
  end if;
  -- Daily selection bootstraps a legacy profile, locks it, and owns today's slot.
  v_daily := public.edge_api_daily(
    p_user_id, p_low, p_reserve, p_active_days, p_today
  );
  select display_name, bio, avatar_url, timezone,
         coalesce(p_today, (now() at time zone timezone)::date) as today
    into v_profile from public.profiles where id = p_user_id;
  if not found then return null; end if;

  if v_daily->>'reason' is null then
    v_availability := 'available';
    v_assignment_slug := v_daily->'concept'->>'slug';
  elsif v_daily->>'reason' = 'personalization_required' then
    v_availability := 'personalization_required';
  else
    v_availability := 'catalog_exhausted';
    if p_reviews then
      v_review := public.edge_api_choose_review(p_user_id, v_profile.today);
      if v_review is not null then v_availability := 'review_available'; end if;
    end if;
  end if;
  if v_daily->>'reason' is not null then v_daily := null; end if;

  v_limit := case when p_compact then 50 else 2147483646 end;
  v_history := public.edge_api_history(p_user_id, null, v_limit);
  v_saved := public.edge_api_saved(p_user_id, null, null, v_limit);
  v_stats := public.edge_api_stats(p_user_id);

  select coalesce(jsonb_agg(t.slug order by t.sort_order), '[]'::jsonb)
    into v_followed from public.user_topics ut
    join public.topics t on t.id = ut.topic_id and t.is_active
   where ut.user_id = p_user_id;
  select coalesce(jsonb_agg(c.slug order by c.slug) filter (where i.liked_at is not null), '[]'::jsonb),
         coalesce(jsonb_agg(c.slug order by c.slug) filter (where i.saved_at is not null), '[]'::jsonb),
         coalesce(jsonb_agg(c.content_version order by c.slug) filter (where i.saved_at is not null), '[]'::jsonb)
    into v_likes, v_bookmarks, v_versions
    from public.concept_interactions i
    join public.concepts c on c.id = i.concept_id and c.status = 'published'
   where i.user_id = p_user_id;

  v_older := null;
  if p_compact then
    v_older := '{}'::jsonb;
    if v_history->>'next_cursor' is not null then
      select coalesce(jsonb_object_agg(topic_name, n), '{}'::jsonb)
        into v_older from (
          select t.name as topic_name, count(*)::integer as n
            from public.daily_assignments a
            join public.concepts c on c.id = a.concept_id and c.status = 'published'
            join public.topics t on t.id = c.topic_id
           where a.user_id = p_user_id and a.completed_at is not null
             and a.assigned_for < (v_history->>'next_cursor')::date
           group by t.name
        ) older;
    end if;
  end if;

  return jsonb_build_object(
    'display_name', v_profile.display_name, 'bio', v_profile.bio,
    'avatar_ref', v_profile.avatar_url, 'avatar_url', null,
    'timezone', v_profile.timezone, 'today', v_profile.today,
    'followed_topics', v_followed, 'learned', v_history->'items',
    'likes', v_likes, 'bookmarks', v_bookmarks,
    'bookmark_versions', v_versions, 'saved', v_saved->'items',
    'stats', v_stats, 'learned_before_window', v_older,
    'history_next_cursor', v_history->'next_cursor',
    'saved_next_cursor', v_saved->'next_cursor',
    'assignment_slug', v_assignment_slug,
    'daily', v_daily, 'daily_availability', v_availability,
    'review', v_review
  );
end
$function$

edge_api_subtopic_quiz.definition:
CREATE OR REPLACE FUNCTION public.edge_api_subtopic_quiz(p_user_id uuid, p_completion_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_completion record;
  v_quiz_id uuid;
  v_questions jsonb;
  v_public jsonb;
  v_reviewed integer;
  v_required integer;
begin
  if not exists(select 1 from auth.users where id = p_user_id) then return null; end if;
  with created as (
    insert into public.profiles(id, display_name)
    select p_user_id, split_part(u.email, '@', 1) from auth.users u
     where u.id = p_user_id
    on conflict(id) do nothing returning id
  )
  insert into public.user_topics(user_id, topic_id)
  select created.id, t.id from created cross join public.topics t where t.is_active
  on conflict do nothing;
  insert into public.notification_preferences(user_id) values(p_user_id)
  on conflict(user_id) do nothing;
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then return null; end if;
  select e.catalog_concept_ids, t.name as topic_name, s.name as subtopic_name
    into v_completion from public.user_subtopic_completions e
    join public.subtopics s on s.id = e.subtopic_id
    join public.topics t on t.id = s.topic_id
   where e.id = p_completion_id and e.user_id = p_user_id;
  if not found then return jsonb_build_object('error', 'unavailable'); end if;
  select id, questions into v_quiz_id, v_questions from public.subtopic_quizzes
   where user_id = p_user_id and subtopic_completion_id = p_completion_id;
  if v_quiz_id is null then
    v_required := least(7, cardinality(v_completion.catalog_concept_ids));
    with candidates as (
      select c.id, c.slug, c.title, c.content_version, c.mcqs,
        pg_catalog.sha256(convert_to(p_completion_id::text || ':select:' || c.id::text, 'UTF8')) as sort_key,
        (get_byte(pg_catalog.sha256(convert_to(
          p_completion_id::text || ':' || c.id::text, 'UTF8')), 0) * 256
         + get_byte(pg_catalog.sha256(convert_to(
          p_completion_id::text || ':' || c.id::text, 'UTF8')), 1)) % 3 as question_index
        from public.concepts c
       where c.id = any(v_completion.catalog_concept_ids)
         and c.status = 'published' and jsonb_typeof(c.mcqs) = 'array'
         and jsonb_array_length(c.mcqs) = 3
       order by sort_key, c.id
       limit v_required
    )
    select count(*)::integer,
      coalesce(jsonb_agg(jsonb_build_object(
        'id', id::text || ':' || content_version::text || ':' || question_index::text,
        'concept_slug', slug, 'concept_title', title,
        'content_version', content_version,
        'question', mcqs -> question_index -> 'question',
        'options', mcqs -> question_index -> 'options',
        'correct_index', mcqs -> question_index -> 'correct_index'
      ) order by sort_key, id), '[]'::jsonb)
      into v_reviewed, v_questions from candidates;
    if v_reviewed < v_required then
      return jsonb_build_object('available', false, 'completion_id', p_completion_id,
        'topic_name', v_completion.topic_name, 'subtopic_name', v_completion.subtopic_name,
        'reviewed_concepts', v_reviewed, 'required_concepts', v_required,
        'detail', 'This optional quiz will unlock when enough reviewed questions are available.');
    end if;
    insert into public.subtopic_quizzes(user_id, subtopic_completion_id, questions)
    values(p_user_id, p_completion_id, v_questions) returning id into v_quiz_id;
  end if;
  select coalesce(jsonb_agg(q.value - 'correct_index' order by q.ordinality), '[]'::jsonb)
    into v_public from jsonb_array_elements(v_questions) with ordinality as q(value, ordinality);
  return jsonb_build_object('available', true, 'quiz_id', v_quiz_id,
    'completion_id', p_completion_id, 'topic_name', v_completion.topic_name,
    'subtopic_name', v_completion.subtopic_name, 'questions', v_public);
end
$function$

edge_api_weekly_quiz.definition:
CREATE OR REPLACE FUNCTION public.edge_api_weekly_quiz(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_week date := current_date - (extract(isodow from current_date)::integer - 1);
  v_quiz_id uuid;
  v_questions jsonb;
  v_public jsonb;
  v_count integer;
begin
  if not exists(select 1 from auth.users where id = p_user_id) then return null; end if;
  with created as (
    insert into public.profiles(id, display_name)
    select p_user_id, split_part(u.email, '@', 1) from auth.users u
     where u.id = p_user_id
    on conflict(id) do nothing returning id
  )
  insert into public.user_topics(user_id, topic_id)
  select created.id, t.id from created cross join public.topics t where t.is_active
  on conflict do nothing;
  insert into public.notification_preferences(user_id) values(p_user_id)
  on conflict(user_id) do nothing;
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then return null; end if;

  select id, questions into v_quiz_id, v_questions
    from public.weekly_quizzes where user_id = p_user_id and week_start = v_week;
  if v_quiz_id is null then
    with recent as (
      select c.id, c.slug, c.title, c.content_version, c.mcqs,
             max(a.completed_at) as completed_at
        from public.daily_assignments a
        join public.concepts c on c.id = a.concept_id
       where a.user_id = p_user_id and a.completed_at is not null
         and c.status = 'published' and jsonb_typeof(c.mcqs) = 'array'
       group by c.id, c.slug, c.title, c.content_version, c.mcqs
      having jsonb_array_length(c.mcqs) = 3
       order by max(a.completed_at) desc, c.id
       limit 7
    ), selected as (
      select recent.*,
        (get_byte(pg_catalog.sha256(convert_to(
          p_user_id::text || ':' || v_week::text || ':' || recent.id::text, 'UTF8')), 0) * 256
         + get_byte(pg_catalog.sha256(convert_to(
          p_user_id::text || ':' || v_week::text || ':' || recent.id::text, 'UTF8')), 1)) % 3
        as question_index
      from recent
    )
    select count(*)::integer,
      coalesce(jsonb_agg(jsonb_build_object(
        'id', id::text || ':' || content_version::text || ':' || question_index::text,
        'concept_slug', slug, 'concept_title', title,
        'content_version', content_version,
        'question', mcqs -> question_index -> 'question',
        'options', mcqs -> question_index -> 'options',
        'correct_index', mcqs -> question_index -> 'correct_index'
      ) order by completed_at desc, id), '[]'::jsonb)
      into v_count, v_questions from selected;
    if v_count < 7 then
      return jsonb_build_object('available', false, 'week_start', v_week,
        'required_concepts', 7, 'available_concepts', v_count,
        'detail', 'Complete more concepts with reviewed questions to unlock this weekly quiz.');
    end if;
    insert into public.weekly_quizzes(user_id, week_start, questions)
    values(p_user_id, v_week, v_questions) returning id into v_quiz_id;
  end if;
  select coalesce(jsonb_agg(q.value - 'correct_index' order by q.ordinality), '[]'::jsonb)
    into v_public from jsonb_array_elements(v_questions) with ordinality as q(value, ordinality);
  return jsonb_build_object('available', true, 'quiz_id', v_quiz_id,
    'week_start', v_week, 'questions', v_public);
end
$function$

